texto = "sol mar sol viento mar sol"
conteo = {}

for palabra in texto.split():
    conteo[palabra] = conteo.get(palabra, 0) + 1

mas_repetida = ""
maximo = 0
for palabra, veces in conteo.items():
    if veces > maximo:
        mas_repetida = palabra
        maximo = veces

print(conteo)
print(f"Más repetida: {mas_repetida} ({maximo} veces)")

